دالة اجمع_المتداخل(خ) {
    متغير م = ٠
    من_أجل (قيمة في قيم(خ)) {
        إذا (نوع(قيمة) == "خريطة") {
            م = م + اجمع_المتداخل(قيمة)
        } وإلا إذا (نوع(قيمة) == "عدد") {
            م = م + قيمة
        }
    }
    ارجع م
}
```

